sealed class Outcome150 {
    data class Success(val payload: String) : Outcome150()
    data object Failure : Outcome150()
}

fun describe150(outcome: Outcome150): String = when (outcome) {
    is Outcome150.Success -> outcome.payload
    Outcome150.Failure -> "failed"
}
data class Pair151<A, B>(val first: A, val second: B)

fun combine151(left: Int, right: Int): Pair151<Int, Int> {
    return Pair151(left + 13, right + 64)
}
